using System;using System.IO;using System.Linq;using System.Text;using System.Text.RegularExpressions;using System.Collections.Generic;
internal sealed class FaultRecord {
 public int SchemaVersion{get;set;}public string Id{get;set;}public string EventTime{get;set;}public string Category{get;set;}public string Operation{get;set;}public string Stage{get;set;}public string Reason{get;set;}public string UserSymptom{get;set;}public bool Demo{get;set;}public bool StatusOnly{get;set;}public bool EventsLimited{get;set;}
 public string DataState{get;set;}public string CleanupState{get;set;}public string DesktopState{get;set;}public string WorkerState{get;set;}public string PlayerState{get;set;}public string RunRelative{get;set;}public string SessionRelative{get;set;}
 public string IncidentId{get;set;}
 public string ProgramVersion{get;set;}public string EntryPath{get;set;}public string ProcessImage{get;set;}public string ExceptionType{get;set;}public string DataLocationStatus{get;set;}public bool StartupFailure{get;set;}public string DiagnosticFailurePath{get;set;}
 public string CatalogId{get;set;}public string ResourceId{get;set;}public string ResourceSha256{get;set;}public string SourcePath{get;set;}public string PreviewConfirmedSha256{get;set;}public string DesktopConfirmedSha256{get;set;}public NameEvidence NameSource{get;set;}
 public int? CardCount{get;set;}public bool RetryAllowed{get;set;}public List<Dictionary<string,object>> Events{get;set;}
}
internal static class FaultSafety {
 internal static string Text(string text,int limit=600){if(text==null)return "";if(text.Length>16384)text=text.Substring(0,16384)+" [输入超长，剩余未采集]";
  text=Regex.Replace(text,@"(?i)(?:https?|wss?)://[^\s\""<>]+","[网络地址已移除]");
  text=Regex.Replace(text,@"(?i)(authorization|cookie|set-cookie|password|passwd|secret|token|api[_-]?key|signature|credential)\s*[=:]\s*[^\r\n,;]+","$1=[已移除]");
  text=Regex.Replace(text,"(?i)[\"']?(authorization|cookie|set-cookie|password|passwd|secret|token|api[_-]?key|signature|credential)[\"'\\s]*[=:][^\\r\\n,;]+","$1=[已移除]");
  text=Regex.Replace(text,@"(?i)\bBearer\s+[A-Za-z0-9._~+/=-]+","[认证内容已移除]");
  text=Regex.Replace(text,@"(?i)\b(?:sk-[A-Za-z0-9_-]{12,}|eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+)\b","[疑似凭据已移除]");
  var b=new StringBuilder();foreach(char c in text){if(Char.IsControl(c)){if(c=='\r'||c=='\n'||c=='\t')b.Append(' ');}else b.Append(c);}string s=b.ToString();return s.Length>limit?s.Substring(0,limit)+" [过长，详细证据见附件；未采集剩余文本]":s;
 }
 internal static string Category(string code){switch(code){case "check":return "资源检查未完成";case "save":return "导入或保存失败";case "start":return "壁纸启动失败";case "stop":return "停止或退出未完成";case "name-cover":return "名称或封面异常";default:return "数据或运行环境异常";}}
 internal static bool SafeRelative(string s){return !String.IsNullOrEmpty(s)&&!Path.IsPathRooted(s)&&!s.Contains(':')&&!s.Split(new[]{'\\','/'}).Any(x=>x==".."||x=="."||x.Length==0);}
 internal static string RelativeLog(string full){try{string root=Path.Combine(Common.Root,"logs");if(!LocalImport.Under(full,root))return null;string rel=full.Substring(Common.Root.TrimEnd('\\').Length+1);return SafeRelative(rel)?rel:null;}catch{return null;}}
 internal static Dictionary<string,object> Fields(Dictionary<string,object> input){var safe=new Dictionary<string,object>();string[] allowed={"state","phase","mode","reason","stage","error","message","cleanupConfirmed","workerState","playerState","exitCode","elapsedSeconds","forced","cancelled","exited","completed","scheduled","sourceId","id","sha256","resourceSha256","expectedSha256","runtimeSha256","sourceSha256","pid","workerPid","controllerPid","creationFileTime","workerCreationFileTime","hwnd","autoPlayed","duplicate","count","changedCards","matched","missing","outcome","readScope","failureKind","exceptionType","exceptionMessage","indexBytesRead","entryBytesRead","responseBytesRead","bodiesRead","requestedCount","matchedCount","missingCount"};foreach(string key in allowed){object value;if(!input.TryGetValue(key,out value)||value==null)continue;if(value is bool||value is int||value is long||value is decimal||value is double)safe[key]=value;else if(value is string)safe[key]=Text((string)value,360);}return safe;}
 internal static Dictionary<string,object> Event(string phase,object data){try{var d=Common.Json.Deserialize<Dictionary<string,object>>(Common.Json.Serialize(data));return new Dictionary<string,object>{{"capturedAt",DateTimeOffset.Now.ToString("o")},{"phase",Text(phase,80)},{"data",Fields(d)}};}catch{return new Dictionary<string,object>{{"phase",Text(phase,80)},{"dataUnavailable",true}};}}
 internal static NameEvidence Name(NameEvidence e){if(e==null)return null;return new NameEvidence{Id=Text(e.Id,24),Name=Text(e.Name,120),Kind=Text(e.Kind,64),CheckedAt=Text(e.CheckedAt,50),SourceSha256=PackageAnalysis.HashText(e.SourceSha256)?e.SourceSha256:null,IndexSha256=PackageAnalysis.HashText(e.IndexSha256)?e.IndexSha256:null,ResponsePath=Text(e.ResponsePath,180),SourceBytes=e.SourceBytes,JsonPath=Text(e.JsonPath,120)};}
 internal static FaultRecord Sanitize(FaultRecord f){if(f==null)throw new InvalidDataException("没有可交接的故障记录");if(f.SchemaVersion!=1||!Regex.IsMatch(f.Id??"","^diag-[0-9]{8}-[0-9]{6}-[a-f0-9]{12}$"))throw new InvalidDataException("诊断记录版本或编号无效");f.Operation=Text(f.Operation,100);f.Stage=Text(f.Stage,140);f.Reason=Text(f.Reason);f.UserSymptom=String.IsNullOrWhiteSpace(f.UserSymptom)?"用户尚未补充":Text(f.UserSymptom,400);f.Category=new[]{"资源检查未完成","导入或保存失败","壁纸启动失败","停止或退出未完成","名称或封面异常","数据或运行环境异常"}.Contains(f.Category)?f.Category:Category("environment");
  f.DataState=Text(f.DataState,240);f.CleanupState=Text(f.CleanupState,240);f.DesktopState=Text(f.DesktopState,240);f.WorkerState=Text(f.WorkerState,30);f.PlayerState=Text(f.PlayerState,30);f.CatalogId=Text(f.CatalogId,120);f.ResourceId=Text(f.ResourceId,80);f.SourcePath=Text(f.SourcePath,600);
  f.ProgramVersion=Text(f.ProgramVersion,120);f.EntryPath=Text(f.EntryPath,600);f.ProcessImage=Text(f.ProcessImage,600);f.ExceptionType=Text(f.ExceptionType,180);f.DataLocationStatus=Text(f.DataLocationStatus,60);f.DiagnosticFailurePath=Text(f.DiagnosticFailurePath,700);
  f.IncidentId=Text(f.IncidentId,60);f.EventTime=Text(f.EventTime,60);if(!PackageAnalysis.HashText(f.ResourceSha256))f.ResourceSha256=null;if(!PackageAnalysis.HashText(f.PreviewConfirmedSha256))f.PreviewConfirmedSha256=null;if(!PackageAnalysis.HashText(f.DesktopConfirmedSha256))f.DesktopConfirmedSha256=null;
  if(!SafeRelative(f.RunRelative)||!f.RunRelative.StartsWith("logs\\",StringComparison.Ordinal))f.RunRelative=null;if(!SafeRelative(f.SessionRelative)||!f.SessionRelative.StartsWith("logs\\",StringComparison.Ordinal))f.SessionRelative=null;f.NameSource=Name(f.NameSource);
  f.Events=(f.Events??new List<Dictionary<string,object>>()).TakeLastCompat(60).Select(x=>{var d=x.ContainsKey("data")?x["data"]as Dictionary<string,object>:null;return new Dictionary<string,object>{{"phase",Text(Common.S(x,"phase"),80)},{"capturedAt",Text(Common.S(x,"capturedAt"),50)},{"data",d==null?new Dictionary<string,object>():Fields(d)}};}).ToList();while(Encoding.UTF8.GetByteCount(Common.Json.Serialize(f.Events))>32768&&f.Events.Count>0){f.Events.RemoveAt(0);f.EventsLimited=true;}return f;
 }
 internal static IEnumerable<T> TakeLastCompat<T>(this IEnumerable<T> source,int count){var list=source.ToList();return list.Skip(Math.Max(0,list.Count-count));}
 internal static string Summary(FaultRecord f){return (f.Demo?"【交接演示，不是真实运行故障】\r\n":"")+(f.StatusOnly?"当前没有记录到具体故障，可补充现象后交接。":f.Operation+"没有完成。")+"\r\n"+f.DataState+"\r\n"+f.CleanupState+"\r\n"+f.DesktopState+"\r\n可以复制故障信息，交给Agent核对处理。";}
}
